use mip_codex::{mps,objective_bound::Certifier,gomory::BoundProof,solve::Result};
use serde::Deserialize;
use std::io::{self,Read};
#[derive(Deserialize)]struct Input{model:String,weights:Vec<f64>}
fn main(){let args:Vec<_>=std::env::args().collect();if args.get(1).is_some_and(|v|v=="build-info"){println!("{}",serde_json::json!({"source_directory":env!("CARGO_MANIFEST_DIR"),"source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT,"library_source_directory":mip_codex::BUILD_SOURCE_DIRECTORY,"library_source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT}));return;}let mut text=String::new();io::stdin().read_to_string(&mut text).unwrap();let inputs:Vec<Input>=serde_json::from_str(&text).unwrap();for input in inputs{let model=mps::parse(std::io::Cursor::new(input.model)).unwrap();let c=Certifier::new(&model).unwrap();let(l,u,steps)=c.infer_box_proof(&model);let bound=c.bound(&l,&u,&input.weights).map(f64::next_down);let proof=bound.map(|b|BoundProof{bounds:steps,normalized_bound:b,multipliers:input.weights.iter().enumerate().filter(|(_,w)|**w!=0.).map(|(i,w)|(i,format!("{:016x}",w.to_bits()))).collect()});let r=Result{status:"unknown".into(),dual_bound:bound.map(|b|if model.maximize{-b}else{b}),gomory_bound_proof:proof,..Result::default()};println!("{}",serde_json::to_string(&r).unwrap());}}
